// Compiles cards/**/*.yaml into src/cards/generated.ts, so no YAML parser ships at runtime.
// `--check` fails when the generated file is out of date (for CI).
import { readFileSync, readdirSync, writeFileSync } from 'node:fs';
import { join, relative } from 'node:path';
import { fileURLToPath } from 'node:url';
import { parse } from 'yaml';
import { z } from 'zod';

const root = fileURLToPath(new URL('..', import.meta.url));
const cardsDir = join(root, 'cards');
const output = join(root, 'src/cards/generated.ts');

const text = z.object({
  title: z.string().min(1),
  summary: z.string().min(1),
  whatIsWrong: z.string().min(1),
  whyItMatters: z.string().min(1),
  howToFix: z.array(z.string().min(1)).min(1),
  short: z.string().min(1),
  technical: z.string().min(1),
});
const priority = z.enum(['critical', 'important', 'minor', 'suggestion']);
const variant = z.object({ priority, pl: text, en: text });
const card = z
  .object({
    id: z.string().regex(/^[a-z0-9]+\/[a-z0-9-]+$/),
    whoFixes: z.enum(['owner', 'developer']),
    effort: z.enum(['small', 'medium', 'large']),
    review: z.enum(['draft', 'reviewed']),
    passed: z.object({ pl: z.string().min(1), en: z.string().min(1) }).optional(),
    priority: priority.optional(),
    pl: text.optional(),
    en: text.optional(),
    variants: z.record(z.string(), variant).optional(),
  })
  .strict();

const squash = (value) => (typeof value === 'string' ? value.replace(/\s+/g, ' ').trim() : value);
const clean = (t) =>
  Object.fromEntries(Object.entries(t).map(([k, v]) => [k, Array.isArray(v) ? v.map(squash) : squash(v)]));

function* yamlFiles(dir) {
  for (const entry of readdirSync(dir, { withFileTypes: true })) {
    const path = join(dir, entry.name);
    if (entry.isDirectory()) yield* yamlFiles(path);
    else if (entry.name.endsWith('.yaml')) yield path;
  }
}

const cards = {};
const errors = [];
for (const file of [...yamlFiles(cardsDir)].sort()) {
  const name = relative(cardsDir, file);
  let source;
  try {
    source = parse(readFileSync(file, 'utf8'));
  } catch (error) {
    errors.push(`${name}: ${error.message.split('\n')[0]}`);
    continue;
  }
  const parsed = card.safeParse(source);
  if (!parsed.success) {
    errors.push(`${name}: ${parsed.error.issues.map((i) => `${i.path.join('.')} ${i.message}`).join('; ')}`);
    continue;
  }
  const c = parsed.data;
  if (`${c.id}.yaml` !== name) errors.push(`${name}: id ${c.id} does not match the file path`);
  const variants =
    c.variants ?? (c.pl && c.en && c.priority ? { default: { priority: c.priority, pl: c.pl, en: c.en } } : null);
  if (!variants) {
    errors.push(`${name}: needs either variants or priority + pl + en`);
    continue;
  }
  for (const [key, v] of Object.entries(variants)) {
    for (const lang of ['pl', 'en']) {
      for (const field of ['title', 'summary', 'whatIsWrong', 'short', 'technical']) {
        const placeholders = (s) =>
          [...s.matchAll(/\{(\w+)/g)]
            .map((m) => m[1])
            .sort()
            .join(',');
        if (placeholders(v.pl[field]) !== placeholders(v.en[field]))
          errors.push(`${name} ${key}.${field}: pl and en use different placeholders`);
      }
      v[lang] = clean(v[lang]);
    }
  }
  cards[c.id] = {
    id: c.id,
    whoFixes: c.whoFixes,
    effort: c.effort,
    review: c.review,
    variants,
    ...(c.passed ? { passed: clean(c.passed) } : {}),
  };
}

if (errors.length) {
  console.error(`Card errors:\n${errors.join('\n')}`);
  process.exit(1);
}

const source = `// Generated by scripts/build-cards.mjs from cards/**/*.yaml. Do not edit by hand.
import type { Card } from './types';

export const cards: Record<string, Card> = ${JSON.stringify(cards, null, 2)};
`;

if (process.argv.includes('--check')) {
  if (readFileSync(output, 'utf8') !== source) {
    console.error('src/cards/generated.ts is out of date. Run: pnpm cards');
    process.exit(1);
  }
  console.log(`${Object.keys(cards).length} cards up to date.`);
} else {
  writeFileSync(output, source);
  console.log(`${Object.keys(cards).length} cards written to src/cards/generated.ts`);
}
